    vals = {v for row in grid for v in row}
    sep = next(v for v in vals
               if sum(all(x == v for x in row) for row in grid) >= 2)
    row_cuts = [i for i, row in enumerate(grid) if all(x == sep for x in row)]
    col_cuts = [j for j in range(w) if all(grid[i][j] == sep for i in range(h))]

    from collections import Counter
    counts = Counter(x for row in grid for x in row if x != sep)
    bg = counts.most_common(1)[0][0]
    mark = next(v for v in vals if v != sep and v != bg)

    rb = [-1] + row_cuts + [h]
    cb = [-1] + col_cuts + [w]
    return [
        [1 if sum(grid[i][j] == mark
                  for i in range(a + 1, b)
                  for j in range(c + 1, d)) >= 2 else bg
         for c, d in zip(cb, cb[1:])]
        for a, b in zip(rb, rb[1:])
    ]
